	private static string CACHE_DURATION_OPTION =
		"Program Cache.Program Cache Time (minutes)";
	private static string CACHE_SIZE_OPTION = "Program Cache.Program Cache Size";
	private static readonly int DEFAULT_PROGRAM_CACHE_CAPACITY = 50;
	private static readonly int DEFAULT_PROGRAM_CACHE_DURATION = 30; // in minutes

	private static readonly string SAVE_GROUP = "DomainObjectSave";
