	private void showProgram(Program p, ProgramLocator locator, int state) {
		if (p == null || p.isClosed()) {
			throw new AssertException("Opened program required");
		}

		Runnable r = () => {
			if (programMgr.addProgram(p, locator, state)) {
				programMgr.saveLocation();
			}
			contextChanged();
		};
		Swing.runNow(r);
	}

